class LibraryError(Exception):
    """Base class for every library rule violation."""


class FineDueError(LibraryError):
    FINE_PER_DAY = 5

    def __init__(self, days_late):
        self.days_late = days_late
        self.fine = days_late * self.FINE_PER_DAY
        super().__init__(f"Returned {days_late} days late: fine ₹{self.fine}")


def return_book(days_kept, allowed=14):
    if days_kept > allowed:
        raise FineDueError(days_kept - allowed)
    return "Returned on time"


print(return_book(10))

slides.tests:
assert issubclass(FineDueError, LibraryError), "FineDueError should inherit from LibraryError."
assert return_book(10) == "Returned on time", "10 days is within the 14 allowed: return 'Returned on time'."
assert return_book(14) == "Returned on time", "Exactly 14 days is still on time."
try:
    return_book(17)
    raise AssertionError("Keeping a book 17 days should raise FineDueError.")
except FineDueError as e:
    assert e.days_late == 3, f"17 days kept with 14 allowed is 3 days late, got {getattr(e, 'days_late', None)}."
    assert e.fine == 15, "3 days late at ₹5 a day is a fine of 15."
    assert str(e) == "Returned 3 days late: fine ₹15", f"The message should be 'Returned 3 days late: fine ₹15', got {str(e)!r}. Pass it to super().__init__."
try:
    return_book(9, allowed=7)
except LibraryError as e:
    assert e.fine == 10, "Use the allowed argument: 9 days with 7 allowed is 2 days late, fine 10."
else:
    raise AssertionError("return_book(9, allowed=7) should raise, because 9 is more than 7.")

