import json
from models import Book, LibraryError, BookUnavailableError, BorrowLimitError


class Member:
    MAX_BOOKS = 3

    def __init__(self, member_id, name, borrowed=None):
        self.member_id = member_id
        self.name = name
        self.borrowed = list(borrowed) if borrowed is not None else []

    def can_borrow(self):
        return len(self.borrowed) < self.MAX_BOOKS

    def to_dict(self):
        return {"member_id": self.member_id, "name": self.name,
                "borrowed": list(self.borrowed)}

    @classmethod
    def from_dict(cls, data):
        return cls(**data)


class Library:
    def __init__(self):
        self.books = {}    # book_id -> Book
        self.members = {}  # member_id -> Member

    def add_book(self, book):
        self.books[book.book_id] = book

    def add_member(self, member):
        self.members[member.member_id] = member

    def _find(self, member_id, book_id):
        if member_id not in self.members:
            raise LibraryError(f"No member with id {member_id}")
        if book_id not in self.books:
            raise LibraryError(f"No book with id {book_id}")
        return self.members[member_id], self.books[book_id]

    def borrow(self, member_id, book_id):
        member, book = self._find(member_id, book_id)
        if not book.available:
            raise BookUnavailableError(f"{book.title} is already borrowed")
        if not member.can_borrow():
            raise BorrowLimitError(f"{member.name} already has {member.MAX_BOOKS} books")
        book.available = False
        member.borrowed.append(book_id)

    def return_book(self, member_id, book_id):
        member, book = self._find(member_id, book_id)
        if book_id not in member.borrowed:
            raise LibraryError(f"{member.name} has not borrowed {book.title}")
        member.borrowed.remove(book_id)
        book.available = True

    def save(self, path):
        data = {"books": [b.to_dict() for b in self.books.values()],
                "members": [m.to_dict() for m in self.members.values()]}
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, indent=2, ensure_ascii=False)

    @classmethod
    def load(cls, path):
        library = cls()
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
        for item in data["books"]:
            library.add_book(Book.from_dict(item))
        for item in data["members"]:
            library.add_member(Member.from_dict(item))
        return library

    def report(self):
        books = sorted(self.books.values(), key=lambda b: b.title)
        lines = [str(b) for b in books]
        out = sum(1 for b in books if not b.available)
        lines.append(f"{len(books)} books, {out} borrowed")
        return "\n".join(lines)


if __name__ == "__main__":
    lib = Library.load("library.json")
    lib.borrow("M1", "B101")
    print(lib.report())

